from pathlib import Path
import json,html
base=Path(__file__).resolve().parent.parent
rows=json.loads((base/'research/prospects.json').read_text())
assert len(rows)==25
intro='''Billy, start with the first 15 courses below. They are all in Oakland or Macomb County, and each has a named contact published by the course. Use the first call to confirm who evaluates and who approves booking software. Our objective is a useful conversation about 2027, followed by a short demonstration only when there is a specific fit.'''
accuracy='''Research checked September 24, 2026. These are course-published business contacts, not phone-confirmed appointments or verified email deliverability. Nineteen courses have a named, currently published leader or routing contact; six have only an official business route suitable for confirming the current buyer. No names, titles, addresses, software contracts, customer results, or purchasing authority have been invented. A published operational contact is not automatically the decision-maker. Historical names are explicitly labeled and must not be used until reconfirmed.'''
software_intro='''Checked against the live CRM and public course websites on September 24, 2026. Of 25 courses, 22 have matching CRM records and 21 have a software value. Public checks found 21 identifiable course-linked booking providers, one Club Prophet store connection only (Novi), one advertised phone-booking route (Richmond Forest), and two unconfirmed setups (Cracklewood and Rammler). A booking link establishes the exposed service, not the complete tee-sheet/POS/payment stack or current contract. No booking was submitted and no CRM records were changed.'''
change_steps=[
('Confirm the actual setup','What runs the staff tee sheet, checkout, payments, website, member accounts and distribution? Which tools are separate? Ask directly; do not infer the entire stack from a booking page.'),
('Find a reason to change','What works well today? What specific problem would make a review worthwhile? Ask how often it happens and what it costs in time or disruption. If there is no meaningful reason to change, respect that.'),
('Protect the operation','List must-keep workflows and people affected: league blocks, member rates, nine-hole routing, future reservations, prepaid bookings, gift cards, rain checks and reports. Confirm which apply at this course.'),
('Map the decision and timing','Who approves, who uses it daily, and who can stop the change? Ask about renewal, notice periods, data access and exports, hardware, payments and bundled services. Do not assume fees or a right to cancel.'),
('Earn an evaluation','Propose a short requirements session with the operator and a staff champion. Agree on representative scenarios and success criteria before a demonstration. Then validate product fit, data handling, training, cutover ownership and a fallback plan before committing to any rollout.'),
('Use the off-season sensibly','Ask for their actual planning window. League setup, prepaid reservations and year-round operations can make a winter change disruptive too. The goal now is a qualified conversation, not an artificial deadline to switch.')]
workflow=[('Before calling','Check existing CRM history, replies, opt-outs, and account ownership. This research does not establish which courses have already been contacted. Start with the first 15, then the four Metro Detroit contact-confirmation calls, then geographic expansion.'),('At the front desk','Hi, this is Billy with TeeAhead, a Metro Detroit tee sheet software company. Your website lists [published name and role]. Are they still the right person to speak with about booking software? If not, who is? For unnamed accounts, ask for the current golf operations manager without guessing a name.'),('When someone answers','Start by confirming the recorded system and its scope. Use the course-specific opening, then listen. Ask what works today, what would need to improve, who approves a change, and when the existing agreement renews. A question in this playbook is a hypothesis to explore, not a claim that the course has a problem.'),('Get a concrete next step','Ask for 15 minutes with the operator who uses the system. Offer to review one sample workflow and return a short requirements summary. If timing is wrong, record a specific month and permission to follow up.'),('After the call','Log the correct name and role, source and confirmation date, phone/email supplied, decision authority, current system as stated, the real problem, next action, due date, and Billy as owner. Use the course-specific email only where appropriate; obtain an address first when none is published.'),('If they say send information','Absolutely. Which booking task should I focus on so I can send something useful? If they have no specific issue, send a short introduction and ask whether a later conversation is welcome.'),('If they are happy or under contract','Respect the answer. Ask whether they want a comparison before their next review or renewal. Do not claim that changing is easy, promise savings, or keep contacting someone who declines.'),('Claims to keep accurate','Position TeeAhead as a local tee sheet software company. Do not promise a golfer audience, integrations, migrations, 27-hole routing, marketing activation, or financial results without verification. Discuss founding-partner pricing only after confirming current written terms. No campaign has been sent and no contacts have been imported by this work.')]
md=['# TeeAhead course outreach playbook for Billy','', '## Metro Detroit first','',intro,'',accuracy,'','## Call order','', '| # | Course | Area | Published contact or route |','|---|---|---|---|']
for i,r in enumerate(rows,1):md.append(f"| {i} | {r['name']} | {r['area']} | {r['contact']} |")
md+=['','## Current software: CRM versus public evidence','',software_intro,'','| Course | CRM value | Public observation | Evidence status |','|---|---|---|---|']
for r in rows:
 sw=r['software']; md.append(f"| {r['name']} | {sw['crm_value'] or ('Blank' if sw['crm_record'] else 'No matching record')} | {sw['public_system']} | {sw['status']} |")
md+=['','## The change-management conversation','']
for h,t in change_steps: md += [f'### {h}','',t,'']
md+=['','## How to work the list','']
for h,t in workflow:md += [f'### {h}','',t,'']
md += ['## Coordinate these accounts','', 'Maple Lane and Cedar Glen publish overlapping contact domains. Greystone and Beacon Hill share an accounting contact, and Beacon Hill advertises cross-course passes. Cherry Creek identifies Pine Trace and Shepherd’s Hollow as sister courses. Myth is managed by Vargo. Fox Hills publishes a Heritage team. These are reasons to confirm the purchasing structure, not proof of identical contracts. Keep one coordinated conversation per buying team.','']
def software_md(r):
 sw=r['software']
 return ['### Current software and verification','', '**CRM record:** '+(sw['crm_record'] or 'No matching course record found.'), '**CRM software value:** '+(sw['crm_value'] or 'Not recorded.'), '**Publicly observed:** '+sw['public_system'], '**Evidence status:** '+sw['status']+' · '+sw['checked'], '',sw['evidence'],'',sw['scope_limit'],'','**Change-management focus:** '+r['change_focus'],'']
for i,r in enumerate(rows,1):
 md += [f"## {i:02d} {r['name']}",'',f"{r['area']} | {r['wave']}",'',f"**Contact status:** {r['status']}",f"**Start with:** {r['contact']}",f"**Phone:** {r['phone']}",f"**Email:** {r['email'] or 'Not verified; call for the correct business email.'}",'',r['alternate'],'',*software_md(r),'### What is established','',r['facts'],'','### Why this conversation','',r['angle'],'','### Billy’s opening','',r['script'],'','**Ask next:** '+r['question'],'','**Next-step ask:** '+r['ask'],'','### Short email','', '**Subject:** '+r['subject'],'',r['email_body'],'','Billy | TeeAhead','', '### Confirm before pitching','',r['check'],'','### Sources','']
 for u in r['sources']:md.append(f'- {u}')
 md.append('')
md += ['## First two weeks','', 'Work toward five substantive operator conversations and two relevant demonstrations. These are working goals, not forecasts. Track contacts reached, conversations held, permission-based next steps, and reasons for no fit. Do not substitute email opens for conversations.','', 'Suggested geographic batches: Macomb/Sterling Heights/Shelby Township; Washington/Lenox/New Baltimore; Clarkston/Oxford/Oakland Township; Commerce/Novi. Schedule visits around actual availability rather than an assumed route or tee-time rush.','']
(base/'Billy-course-outreach-playbook.md').write_text('\n'.join(md))
E=html.escape
def software_html(r):
 sw=r['software']
 return f'<section class="software"><h3>Current software and verification</h3><p><b>CRM record:</b> {E(sw["crm_record"] or "No matching record found")}<br><b>CRM value:</b> {E(sw["crm_value"] or "Not recorded")}<br><b>Public observation:</b> {E(sw["public_system"])}<br><b>Evidence:</b> {E(sw["status"])} · {E(sw["checked"])}</p><p>{E(sw["evidence"])}</p><p class="sources">{E(sw["scope_limit"])}</p><p><b>Change-management focus:</b> {E(r["change_focus"])}</p></section>'
blocks=[]
for i,r in enumerate(rows,1):
 links=' · '.join(f'<a href="{E(u)}" target="_blank" rel="noreferrer">Source {j}</a>' for j,u in enumerate(r['sources'],1))
 blocks.append(f'''<article id="course-{i}"><div class="eyebrow">{E(r['wave'])} · {E(r['area'])}</div><h2>{i:02d} {E(r['name'])}</h2><div class="contact"><strong>{E(r['contact'])}</strong><p>{E(r['status'])} · {E(r['phone'])}<br>{E(r['email']) if r['email'] else 'Email not verified — call for the correct address.'}</p><p>{E(r['alternate'])}</p></div>{software_html(r)}<h3>What is established</h3><p>{E(r['facts'])}</p><h3>Why this conversation</h3><p>{E(r['angle'])}</p><h3>Billy’s opening</h3><blockquote>{E(r['script'])}</blockquote><p><b>Ask next</b> {E(r['question'])}</p><p><b>Next step</b> {E(r['ask'])}</p><h3>Short email</h3><div class="email"><b>Subject: {E(r['subject'])}</b><p>{E(r['email_body'])}</p><p>Billy | TeeAhead</p></div><h3>Confirm before pitching</h3><p>{E(r['check'])}</p><p class="sources">Checked September 24, 2026 · {links} · <a href="#top">Back to list</a></p></article>''')
index=''.join(f'<tr><td>{i:02d}</td><td><a href="#course-{i}">{E(r["name"])}</a><small>{E(r["area"])}</small></td><td>{E(r["contact"])}</td></tr>' for i,r in enumerate(rows,1))
software_table='<section class="guide"><h2>Current software: recorded vs. observed</h2><p>'+E(software_intro)+'</p><div class="table-scroll"><table><thead><tr><th>Course</th><th>CRM value</th><th>Public observation</th><th>Evidence</th></tr></thead><tbody>'+''.join(f'<tr><td>{E(r["name"])}</td><td>{E(r["software"]["crm_value"] or ("Blank" if r["software"]["crm_record"] else "No matching record"))}</td><td>{E(r["software"]["public_system"])}</td><td>{E(r["software"]["status"])}</td></tr>' for r in rows)+'</tbody></table></div></section>'
change_guide='<section class="guide"><h2>The change-management conversation</h2>'+''.join(f'<h3>{E(h)}</h3><p>{E(t)}</p>' for h,t in change_steps)+'</section>'
guide=''.join(f'<h3>{E(h)}</h3><p>{E(t)}</p>' for h,t in workflow)
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TeeAhead outreach playbook for Billy</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f5f4ee;color:#213128;font:16px/1.6 system-ui,sans-serif}}main{{max-width:980px;margin:auto;padding:48px 28px}}header{{padding:36px 0}}h1{{font-size:clamp(32px,5vw,50px);line-height:1.1;letter-spacing:-1.5px;max-width:740px}}h2{{font-size:28px;line-height:1.25;margin:10px 0 22px}}h3{{font-size:15px;margin:24px 0 8px}}p{{margin:10px 0}}.eyebrow{{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#596c60;font-weight:700}}.note,.contact,.email{{padding:20px;background:#eef2eb;border-radius:10px}}.note{{border-left:4px solid #b88d32;background:#fff8e8}}article,.guide,.index{{padding:32px;background:white;margin:28px 0;border:1px solid #dce2d8;border-radius:16px;scroll-margin-top:20px}}article{{break-before:page}}blockquote{{margin:12px 0;padding:18px 22px;border-left:3px solid #2c654b;background:#f3f6f2;font-size:18px}}table{{width:100%;border-collapse:collapse;font-size:14px}}td,th{{text-align:left;vertical-align:top;padding:12px 8px;border-bottom:1px solid #e4e8e1}}small{{display:block;color:#647167}}a{{color:#22573f;text-underline-offset:3px}}.sources{{font-size:12px;color:#647167}}.email{{background:#f7f7f3}}.software{{background:#f4f6f7;border-left:3px solid #647b88;padding:4px 18px 12px;margin-top:20px}}.table-scroll{{overflow-x:auto}}.table-scroll table{{min-width:650px}}@media(max-width:600px){{main{{padding:18px 12px}}article,.guide,.index{{padding:22px 16px}}h2{{font-size:25px}}td,th{{padding:10px 4px;font-size:12px}}blockquote{{padding:14px;font-size:16px}}}}@media print{{body{{background:white;font-size:10pt}}main{{padding:0;max-width:none}}article,.guide,.index{{border:0;padding:0;border-radius:0}}article{{break-before:page}}h2,h3{{break-after:avoid}}p,blockquote,.contact,.email{{break-inside:avoid}}a{{color:inherit}}.sources{{font-size:9pt}}}} </style></head><body><main id="top"><header><div class="eyebrow">TeeAhead · September 24, 2026 · Prepared for Billy</div><h1>25 course conversations<br>Start in Metro Detroit</h1><p>{E(intro)}</p></header><div class="note"><b>Contact accuracy</b><p>{E(accuracy)}</p></div><section class="index"><h2>Call order</h2><p>01–15: named Metro Detroit contacts. 16–19: local buyer-confirmation calls. 20–25: expansion and longer-term relationships.</p><table><thead><tr><th>#</th><th>Course</th><th>Published contact or route</th></tr></thead><tbody>{index}</tbody></table></section>{software_table}{change_guide}<section class="guide"><h2>How to work the list</h2>{guide}<h3>Coordinate shared buying teams</h3><p>Ask about shared purchasing at Maple Lane and Cedar Glen, Greystone and Beacon Hill, Cherry Creek and its sister courses, Myth and Vargo, and Fox Hills and Heritage. Do not run simultaneous independent pitches into the same organization.</p></section>{''.join(blocks)}</main></body></html>'''
(base/'Billy-course-outreach-playbook.html').write_text(page)
print('Created 25 profiles; named course-published contacts:',sum(r['status']!='Official business route only' for r in rows))
